class Solution { public: int numPermsDISequence(string s){const long long mod=1000000007;vector<long long> dp{1};for(char relation:s){vector<long long> next(dp.size()+1);if(relation=='I')for(int j=1;j<(int)next.size();++j)next[j]=(next[j-1]+dp[j-1])%mod;else for(int j=dp.size()-1;j>=0;--j)next[j]=(next[j+1]+dp[j])%mod;dp.swap(next);}return accumulate(dp.begin(),dp.end(),0LL)%mod;} };
